extra-factorial-recursive.code:
#include <stdio.h>
unsigned long long fact(int n) {
    if (n == 0 || n == 1) return 1;
    return (unsigned)n * fact(n - 1);
}
int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 0 || n > 20) return 1;
    printf("%d! = %llu\n", n, fact(n));
    return 0;
}

extra-fibonacci.code:
#include <stdio.h>
int fib(int m) {
    if (m == 0) return 0;
    else if (m == 1) return 1;
    else return fib(m - 1) + fib(m - 2);
}
int main(void) {
    int n, i;
    if (scanf("%d", &n) != 1 || n < 0 || n > 20) return 1;
    for (i = 0; i < n; i++) printf("%d%c", fib(i), i == n - 1 ? '\n' : ' ');
    return 0;
}

selection-sort.code:
#include <stdio.h>
int main(void) {
    int a[100], n;
    if (scanf("%d", &n) != 1 || n < 1 || n > 100) return 1;
    for (int i = 0; i < n; ++i)
        if (scanf("%d", &a[i]) != 1) return 1;
    for (int i = 0; i < n - 1; ++i) {
        int min_index = i;
        for (int j = i + 1; j < n; ++j)
            if (a[j] < a[min_index]) min_index = j;
        if (min_index != i) {
            int temp = a[i];
            a[i] = a[min_index];
            a[min_index] = temp;
        }
    }
    for (int i = 0; i < n; ++i)
        printf("%d%s", a[i], i == n - 1 ? "\n" : " ");
    return 0;
}

