u3-value-pointer.code:
#include <stdio.h>
void swap_value(int x, int y) {
    int temp = x; x = y; y = temp;
}
void swap(int *x, int *y) {
    int temp = *x; *x = *y; *y = temp;
}
int main(void) {
    int a, b;
    if (scanf("%d%d", &a, &b) != 2) return 1;
    printf("Before: %d %d\n", a, b);
    swap_value(a, b);
    printf("After value: %d %d\n", a, b);
    swap(&a, &b);
    printf("After pointer: %d %d\n", a, b);
    return 0;
}

u3-ackermann.code:
#include <stdio.h>
static unsigned long calls;
static int exceeded;
unsigned long ack(unsigned m, unsigned long n) {
    if (++calls > 1000000UL) { exceeded = 1; return 0; }
    if (m == 0) return n + 1;
    if (n == 0) return ack(m - 1, 1);
    return ack(m - 1, ack(m, n - 1));
}
int main(void) {
    unsigned m;
    unsigned long n, result;
    if (scanf("%u%lu", &m, &n) != 2 || m > 3 || n > 6) return 1;
    result = ack(m, n);
    if (exceeded) { fputs("Call limit exceeded\n", stderr); return 1; }
    printf("A(%u,%lu) = %lu\n", m, n, result);
    return 0;
}

