#include <stdio.h>
unsigned long gcd(unsigned long a, unsigned long b) {
    if (b == 0) return a;
    return gcd(b, a % b);
}
int main(void) {
    unsigned long a, b;
    if (scanf("%lu%lu", &a, &b) != 2 || a > 1000000UL || b > 1000000UL || (a == 0 && b == 0)) return 1;
    printf("GCD: %lu\n", gcd(a, b));
    return 0;
}

