u3-matrix-functions.code:
#include <stdio.h>
void multiply(int a[3][3], int b[3][3], long c[3][3]) {
    int i, j, k;
    for (i = 0; i < 3; i++) {
        for (j = 0; j < 3; j++) {
            c[i][j] = 0;
            for (k = 0; k < 3; k++) c[i][j] += (long)a[i][k] * b[k][j];
        }
    }
}
int main(void) {
    int a[3][3], b[3][3], i, j;
    long c[3][3];
    for (i = 0; i < 3; i++) for (j = 0; j < 3; j++)
        if (scanf("%d", &a[i][j]) != 1 || a[i][j] < -100 || a[i][j] > 100) return 1;
    for (i = 0; i < 3; i++) for (j = 0; j < 3; j++)
        if (scanf("%d", &b[i][j]) != 1 || b[i][j] < -100 || b[i][j] > 100) return 1;
    multiply(a, b, c);
    for (i = 0; i < 3; i++) for (j = 0; j < 3; j++)
        printf("%ld%c", c[i][j], j == 2 ? '\n' : ' ');
    return 0;
}

u3-bubble.code:
#include <stdio.h>
void sort(int b[], int m) {
    int i, j, temp;
    for (i = 0; i < m - 1; i++) {
        for (j = 0; j < m - 1 - i; j++) {
            if (b[j] > b[j + 1]) { temp = b[j]; b[j] = b[j + 1]; b[j + 1] = temp; }
        }
    }
}
int main(void) {
    int a[20], n, i;
    if (scanf("%d", &n) != 1 || n < 1 || n > 20) return 1;
    for (i = 0; i < n; i++) if (scanf("%d", &a[i]) != 1) return 1;
    printf("Before:");
    for (i = 0; i < n; i++) printf(" %d", a[i]);
    sort(a, n);
    printf("\nAfter:");
    for (i = 0; i < n; i++) printf(" %d", a[i]);
    putchar('\n');
    return 0;
}

u3-insertion.code:
#include <stdio.h>
int main(void) {
    int a[100], n, i, j, key;
    if (scanf("%d", &n) != 1 || n < 1 || n > 100) return 1;
    for (i = 0; i < n; i++) if (scanf("%d", &a[i]) != 1) return 1;
    for (i = 1; i < n; i++) {
        key = a[i]; j = i - 1;
        while (j >= 0 && a[j] > key) { a[j + 1] = a[j]; j--; }
        a[j + 1] = key;
    }
    for (i = 0; i < n; i++) printf("%d%c", a[i], i == n - 1 ? '\n' : ' ');
    return 0;
}

